import{_ as t,o as e,c as s,a2 as n}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"本地数据模型","description":"Turna 同时包含内容真理源、派生缓存和用户状态。维护操作必须先区分三者。","frontmatter":{"description":"Turna 同时包含内容真理源、派生缓存和用户状态。维护操作必须先区分三者。"},"headers":[],"relativePath":"developer/local-data.md","filePath":"developer/local-data.md","lastUpdated":1787830168000}'),i={name:"developer/local-data.md"};function d(l,a,r,o,p,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="本地数据模型" tabindex="-1">本地数据模型 <a class="header-anchor" href="#本地数据模型" aria-label="Permalink to &quot;本地数据模型&quot;">​</a></h1><p>Turna 同时包含内容真理源、派生缓存和用户状态。维护操作必须先区分三者。</p><h2 id="分层" tabindex="-1">分层 <a class="header-anchor" href="#分层" aria-label="Permalink to &quot;分层&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bundle course JSON        authoritative content</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        | versioned seed</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>drift course database     runtime projection/cache</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>user progress / SRS       authoritative local user state</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>Official Anki Collection  authoritative imported-card state</span></span></code></pre></div><h2 id="课程导入" tabindex="-1">课程导入 <a class="header-anchor" href="#课程导入" aria-label="Permalink to &quot;课程导入&quot;">​</a></h2><p>应用启动先加载 <code>index.json</code> 的 Section shell。打开 Section 时加载 Unit / Lesson 元数据，打开 Lesson 时加载内容。作者仍编辑完整 JSON；分层加载只是运行策略。</p><p>内容版本变化触发 reseed。reseed 更新课程投影，不应清除独立的用户复习历史。</p><h2 id="主要数据域" tabindex="-1">主要数据域 <a class="header-anchor" href="#主要数据域" aria-label="Permalink to &quot;主要数据域&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据域</th><th>示例</th><th>维护方式</th></tr></thead><tbody><tr><td>课程投影</td><td>Section、Unit、Lesson、资源</td><td>由 JSON reseed</td></tr><tr><td>学习进度</td><td>completed Lesson、统计</td><td>应用事务</td></tr><tr><td>SRS</td><td>state、due、review event</td><td>调度事务</td></tr><tr><td>错题</td><td>interaction snapshot</td><td>错误事件写入</td></tr><tr><td>Official Anki</td><td>notes、cards、revlog、scheduler</td><td>Official Core（独立于 course.db 的库）</td></tr><tr><td>AI</td><td>会话、消息、诊断、指标</td><td>AI 工作流</td></tr><tr><td>设置</td><td>主题、无障碍、课程 TTS</td><td>本地偏好</td></tr><tr><td>缓存</td><td>AI 响应缓存、复习看板快照、图片缓存</td><td>可再生成</td></tr></tbody></table><h2 id="事务边界" tabindex="-1">事务边界 <a class="header-anchor" href="#事务边界" aria-label="Permalink to &quot;事务边界&quot;">​</a></h2><p>一次复习评分应原子地更新当前状态和历史记录。媒体复制、外部 AI 请求或长耗时解析不能被伪装成同一个数据库事务；失败时使用明确的阶段状态和补偿策略。</p><h2 id="schema-迁移" tabindex="-1">Schema 迁移 <a class="header-anchor" href="#schema-迁移" aria-label="Permalink to &quot;Schema 迁移&quot;">​</a></h2><p>数据库 schema 只向前迁移。遇到未来 schema 版本时拒绝降级打开，防止旧客户端破坏新数据。迁移测试必须覆盖现有旧版本到当前版本的路径。</p><p>文档中的具体 schemaVersion 是时间敏感实现细节。诊断报告应读取运行版本，不硬编码文档数值作为判断依据。</p><h2 id="完整性与优化" tabindex="-1">完整性与优化 <a class="header-anchor" href="#完整性与优化" aria-label="Permalink to &quot;完整性与优化&quot;">​</a></h2><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PRAGMA integrity_check;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REINDEX;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PRAGMA optimize;</span></span></code></pre></div><p>完整性检查是只读操作。REINDEX 与 optimize 维护索引和查询计划，不删除业务数据。</p><h2 id="缓存清理" tabindex="-1">缓存清理 <a class="header-anchor" href="#缓存清理" aria-label="Permalink to &quot;缓存清理&quot;">​</a></h2><p>允许直接再生成的典型数据：</p><ul><li>AI 响应缓存。</li><li>复习看板快照。</li><li>运行时图片缓存。</li><li>可重新导入的课程投影，但执行前必须保护用户状态。</li></ul><p>历史遗留的 Anki 预渲染 HTML 缓存（&quot;智能去解密&quot;）已在 schema v22 被删除、该路径明文放弃，不在上述清单内。</p><p>不属于普通缓存：SRS、review history、Official Collection、错题、AI 会话、用户设置。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/developer/architecture">架构总览</a></li></ul>`,24)])])}const b=t(i,[["render",d]]);export{u as __pageData,b as default};
